<?php
namespace Tests\Feature;use App\Models\{CompanyContent,Destination,GalleryAlbum,GalleryCategory,NavigationItem,Tour,User,VisaService,Word};use Database\Seeders\CmsPermissionSeeder;use Illuminate\Foundation\Testing\RefreshDatabase;use Spatie\Permission\Models\Role;use Tests\TestCase;
class DomainAdminCrudTest extends TestCase{use RefreshDatabase;private function admin():User{Role::firstOrCreate(['name'=>'superadmin','guard_name'=>'web']);$u=User::factory()->create();$u->assignRole('superadmin');return $u;}private function login():void{$this->seed(CmsPermissionSeeder::class);$this->actingAs($this->admin());}
 public function test_navigation_crud_and_filter():void{$this->login();$this->post(route('navigation-items.store'),['location'=>'header','url'=>'/test','target'=>'_self','sort_order'=>1,'is_active'=>1,'en'=>['title'=>'Test Link']])->assertRedirect();$item=NavigationItem::first();$this->get(route('navigation-items.index',['q'=>'Test']))->assertOk()->assertSee('Test Link');$this->put(route('navigation-items.update',$item),['location'=>'footer_company','url'=>'/updated','target'=>'_blank','is_active'=>1,'en'=>['title'=>'Updated Link']])->assertRedirect();$this->assertDatabaseHas('navigation_item_translations',['title'=>'Updated Link']);$this->delete(route('navigation-items.destroy',$item))->assertRedirect();$this->assertSoftDeleted($item);}
 public function test_visa_service_crud_filter_and_relation():void{$this->login();$destination=Destination::create(['type'=>'country','is_active'=>1,'en'=>['name'=>'Japan','slug'=>'japan']]);$payload=['destination_id'=>$destination->id,'price'=>129,'currency'=>'CAD','processing_time'=>'5 days','is_active'=>1,'en'=>['name'=>'Japan Visa','description'=>'Review','required_documents'=>'Passport','disclaimer'=>'No guarantee']];$this->post(route('domain-content.store','visa-services'),$payload)->assertRedirect();$visa=VisaService::first();$this->get(route('domain-content.index',['visa-services','q'=>'Japan']))->assertOk()->assertSee('Japan Visa');$payload['price']=149;$payload['en']['name']='Updated Visa';$this->put(route('domain-content.update',['visa-services',$visa]),$payload)->assertRedirect();$this->assertDatabaseHas('visa_services',['id'=>$visa->id,'destination_id'=>$destination->id,'price'=>149]);$this->delete(route('domain-content.destroy',['visa-services',$visa]))->assertRedirect();$this->assertSoftDeleted($visa);}
 public function test_gallery_category_album_media_cruds_and_relations():void{$this->login();$this->post(route('domain-content.store','gallery-categories'),['is_active'=>1,'en'=>['name'=>'Nature','slug'=>'nature']])->assertRedirect();$category=GalleryCategory::first();$tour=Tour::create(['duration_days'=>1,'duration_nights'=>0,'status'=>'published','en'=>['name'=>'Tour','slug'=>'tour']]);$this->post(route('domain-content.store','gallery-albums'),['gallery_category_id'=>$category->id,'tour_id'=>$tour->id,'tour_date'=>'2026-05-10','cover_image'=>'cover.jpg','is_active'=>1,'en'=>['title'=>'Album','description'=>'Trip photos']])->assertRedirect();$album=GalleryAlbum::first();$this->post(route('gallery-media.store',$album),['type'=>'image','path'=>'photo.jpg','en'=>['alt_text'=>'Photo','caption'=>'Caption']])->assertRedirect();$medium=$album->media()->first();$this->assertDatabaseHas('gallery_media',['gallery_album_id'=>$album->id,'path'=>'photo.jpg']);$this->delete(route('gallery-media.destroy',[$album,$medium]))->assertRedirect();$this->assertDatabaseMissing('gallery_media',['id'=>$medium->id]);$this->delete(route('domain-content.destroy',['gallery-albums',$album]))->assertRedirect();$this->delete(route('domain-content.destroy',['gallery-categories',$category]))->assertRedirect();}
 public function test_company_content_and_ui_word_complete_cruds():void{$this->login();$this->post(route('company-content.store'),['type'=>'team','image'=>'person.jpg','is_active'=>1,'en'=>['title'=>'Jane Doe','subtitle'=>'Guide','description'=>'Bio']])->assertRedirect();$content=CompanyContent::first();$this->get(route('company-content.index',['type'=>'team','q'=>'Jane']))->assertOk()->assertSee('Jane Doe');$this->put(route('company-content.update',$content),['type'=>'partner','is_active'=>1,'en'=>['title'=>'Updated Partner']])->assertRedirect();$this->assertDatabaseHas('company_contents',['id'=>$content->id,'type'=>'partner']);$this->delete(route('company-content.destroy',$content))->assertRedirect();$this->assertSoftDeleted($content);
  $this->post(route('words.store'),['key'=>'test.copy','source'=>'Original copy','en'=>['title'=>'Displayed copy']])->assertRedirect();$word=Word::first();$this->get(route('words.index',['q'=>'Displayed']))->assertOk()->assertSee('Displayed copy');$this->put(route('words.update',$word),['key'=>'test.copy','source'=>'Original copy','en'=>['title'=>'Updated copy']])->assertRedirect();$this->assertDatabaseHas('word_translations',['title'=>'Updated copy']);$this->delete(route('words.destroy',$word))->assertRedirect();$this->assertSoftDeleted($word);}
 public function test_domain_content_requires_permission():void{$this->actingAs(User::factory()->create())->get(route('domain-content.index','visa-services'))->assertForbidden();}
}
